import logging
from nicegui import ui
import random
import sys
import os

# ---------- 路径处理 ----------
def get_file_path(filename):

    if hasattr(sys, '_MEIPASS'):# noinspection PyProtectedMember
        return os.path.join(sys._MEIPASS, filename)
    return os.path.join(os.path.dirname(__file__), filename)


# ---------- 全局变量 ----------
count = 0
win_animation = None
win_timer = None
win_audio = None

# ---------- 强制背景 ----------
ui.add_head_html('''
<style>
    body {
        background: url("data:image/jpeg;base64,") no-repeat center center fixed !important;
        background-size: cover !important;
        min-height: 100vh !important;
        margin: 0 !important;
        padding: 0 !important;
    }
</style>
''')
AUDIO_BASE64 = "data:audio/mpeg;base64,"

# ---------- 抽奖逻辑 ----------
def draw():
    global count, win_animation, win_timer,win_audio
    count += 1
    num = random.randint(1, 100)
    result.set_text(f'Honey cake drop rate: {num} %')
    count_label.set_text(f'Attempts:{count} ')
    result.classes('animate-pulse')

    if num == 100:
        # 移除旧动画和旧音效
        if win_animation:
            win_animation.delete()
        if win_timer:
            win_timer.cancel()

        gif_path = get_file_path('xi.gif')
        # GIF 放在卡片外面，避免被遮挡
        win_animation = ui.image(gif_path).classes('w-72 h-72 mx-auto mt-4')
        win_audio = ui.audio(AUDIO_BASE64, autoplay=True, controls=False)
        win_audio.classes('hidden')
        win_timer = ui.timer(15, lambda: hide_win_animation(), once=True)
    else:
        hide_win_animation()


def hide_win_animation():
    global win_animation, win_timer, win_audio  #
    if win_animation:
        win_animation.delete()
        win_animation = None
    if win_timer:
        win_timer.cancel()
        win_timer = None
    if win_audio:
        win_audio.delete()  #
        win_audio = None


# ---------- 界面 ----------
with ui.card().classes('mx-auto mt-20 p-8 rounded-2xl shadow-2xl').style(
        'width: 450px; background: rgba(0,0,0,0.3); backdrop-filter: blur(12px);'):
    ui.label('We have come for the truth of the honey cake').classes('text-3xl font-bold text-white text-center')
    result = ui.label('Refusing to forget the truth').classes('text-5xl text-center my-6 py-4 px-2 rounded-xl').style(
        'color: #FFD700; background: rgba(0,0,0,0.2);')
    ui.button('Take a brave leap', on_click=draw).classes('w-full text-lg py-3').props('color=red glossy')
    count_label = ui.label('Attempts 0 ').classes('text-white text-center mt-4 opacity-80')


# ---------- 修复打包后日志报错 ----------
# 1. 环境变量：让 uvicorn 彻底闭嘴
os.environ["UVICORN_LOG_LEVEL"] = "CRITICAL"

# 2. 获取所有已存在的 logger
for name in logging.root.manager.loggerDict:
    if name.startswith("uvicorn"):
        logger = logging.getLogger(name)
        logger.handlers = []          # 清空所有处理器
        logger.propagate = False      # 阻止传播到根 logger
        logger.setLevel(logging.CRITICAL)

# 3. 额外预防：把 uvicorn 的 access 和 error logger 也单独处理
for name in ["uvicorn", "uvicorn.access", "uvicorn.error"]:
    logger = logging.getLogger(name)
    logger.handlers = []
    logger.propagate = False
    logger.setLevel(logging.CRITICAL)
# ---------- 启动程序 ----------
ui.run(
    title='We have come for the truth of the honey cake',
    port=8000,
    show=True,
    native=False,
    reload=False
)
